def solve(rows):
    state = 6
    kept_rows = []
    for i, row in enumerate(rows):
        weight = 0
        if isinstance(row, int):
            weight = row
        elif isinstance(row, str) and row.startswith("|") and row.endswith("||"):
            try:
                weight = int(row[1:-2])
            except ValueError:
                weight = 0
        elif isinstance(row, list):
            for item in row:
                if isinstance(item, int):
                    weight += item
                elif isinstance(item, str):
                    weight += len(item)

        if (state + weight + i) % 11 != 10 or i == len(rows) - 1:
            kept_rows.append(row)

        if weight == 0:
            state = 6
        else:
            state = (3 * state + weight) % 11

    if not kept_rows:
        return []

    final_state = state
    kept_length = len(kept_rows)
    rotation_amount = final_state % kept_length
    rotated_rows = kept_rows[rotation_amount:] + kept_rows[:rotation_amount]

    eligible_days = []
    for row in rotated_rows:
        if isinstance(row, list) and len(row) == 2:
            day, is_blackout = row
            if not is_blackout and day % 5 != 0:
                eligible_days.append(day)

    eligible_days = sorted(list(set(eligible_days)))[:4]
    return eligible_days

